---GetCombatData
---获取战斗训练关卡表,将sortId提取出来作为key
function BattlingCombatLevelMgr:GetCombatData()
    local tableFile = SettingMgr:Get(AutoIds.IdSetting924)
    local CombatLevelsVo = import('Game.Setting.Vo.CombatLevelsVo')
    local combatLevelsVoList = {}
    for i, row in pairs(tableFile) do
        local vo = CombatLevelsVo.New()
        vo:FillVo(row)
        if combatLevelsVoList[vo.sortId] then
            table.insert(combatLevelsVoList[vo.sortId], vo)
        else
            combatLevelsVoList[vo.sortId] = {}
            table.insert(combatLevelsVoList[vo.sortId], vo)
        end
    end
    return combatLevelsVoList
end

---CheckQuestData
---检查 QuestId 是否有新手任务
---@param questId number 关卡ID
function BattlingCombatLevelMgr:CheckQuestData(questId)
    self.curQuestId = questId --- 当前关卡 ID
    local aimData
    for i = 1, #self.combatData do
        local questData = self.combatData[i]
        for j = 1, #questData do
            local curveData = questData[j]
            local curQuestId = curveData.id
            if curQuestId == questId then
                aimData = curveData
                self.curQuestData = curveData
            end
        end
    end
    return aimData
end

