function BattlingCombatLevelMgr:GetStarQuest(questId)
    local isStarQuest
    local type = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    if  type == Constants.IDType.QuestCoinsCopy or
            type == Constants.IDType.QuestExpCopy or
            type == Constants.IDType.QuestUpStarCopy or
            type == Constants.IDType.QuestMainChallenge or
            type == Constants.IDType.QuestMediumPT or
            type == Constants.IDType.QuestBambooChanllenge or
            type == Constants.IDType.QuestHalloween then
        isStarQuest = true
    end
    return checkBool(isStarQuest)
end

function BattlingCombatLevelMgr:UpdateQuestConditionData(questId, wave)
    self.listWaveCondition = {}
    local waveVo = Core:GetLevelData(questId)[wave]
    if isNull(waveVo) then return end
    local victory = waveVo.victory
    local defeat = waveVo.defeat
    --todo 当前条件值只取胜利条件, 只取第条件列表一个， _21_10_28_
    if isNull(victory) or isNull(victory[1]) then return end
    local conditionVictory = victory[1]
    local conditionData = self:GetWaveEndConditionData(conditionVictory)
    local isShow = checkNumber(conditionData.show) > 0
    if not checkBool(isShow) then return end
    for i, preData in pairs(conditionData.conditions) do
        --- row 条件表_子条件类型_描述参数
        for j, data in pairs(preData) do
            local typeId = data.type
            local conditionPara = checkInt(data.conditionParam) -- 替换 _diff_
            local targetNum = checkInt(data.targetNum) -- 替换 _target_num_, 同时也作为 进度值
            local group = i -- 条件关系（决定type字段所使用的条件归类的组。如果同一组，则表示且。非同一组为或关系。）
            --- 每条条件从 条件类型表里 取描述
            local conditionTypeVo = self:GetWaveEndConditionTypeData(typeId)
            local conditionDesc = conditionTypeVo.condition
            local conditionShowType = checkInt(conditionTypeVo.showType) -- 显示类型（1.显示进度与条件, 2.不显示进度, 3. "0"或空则完全不显示）
            if conditionShowType < 1 then goto continue end
            local desc = self:SetConditionDesc(conditionDesc, conditionPara, targetNum, typeId)
            local process = conditionShowType == 1 and targetNum or 0
            local _conditionData = ConditionData.New(typeId, group, desc, process)
            table.insert(self.listWaveCondition, _conditionData)
            :: continue ::
        end
    end
end

function BattlingCombatLevelMgr:GetStarConditionsData(questId)
    if self.listWaveCondition and #self.listWaveCondition > 0 then return end
    self.listWaveCondition = {}
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    if isNull(vo) then return end
    local starCondition = vo["starCondition"] or vo["conditionId"]
    local starConditionNum = vo["starConditionNum"] or vo["conditionValue"]
    if Tools.isNullKey(starCondition) then return end
    local listStarConditions = CfUtils.Split(starCondition)
    local listStarConditionNum = CfUtils.Split(starConditionNum)
    local _, conditionDatas = QuestConfMgr:GetInstance():GetQuestConditions(questId)
    for i = 1, #listStarConditions do
        local conditionTypeId = checkString(listStarConditions[i])
        local questTypeVo = checkTable(CfUtils.GetCfVo(AutoIds.IdSetting820, "QuestConditionVo", conditionTypeId))
        local conditionShowType = checkInt(questTypeVo.showType) -- 显示类型（1.显示进度与条件, 2.不显示进度, 3. "0"或空则完全不显示）
        -- print("->UICondition1:", conditionShowType)
        if conditionShowType < 1 then goto continue end
        local typeId = checkNumber(questTypeVo.type)
        local group = i
        local desc = checkString(conditionDatas[i].desc)
        local targetNum = checkNumber(listStarConditionNum[i])
        local process = (conditionShowType == ShowType.ShowTarget or conditionShowType == ShowType.ShowPre) and targetNum or 0
        local _conditionData = ConditionData.New(typeId, group, desc, process, conditionShowType)
        table.insert(self.listWaveCondition, _conditionData)
        :: continue ::
    end
    -- print("->UICondition2:", table.dump(self.listWaveCondition))
end

function BattlingCombatLevelMgr:FieldDiffTranslator(conditionPara, typeId)
    local value = conditionPara
    if typeId then
        ---怪物类型表
        if checkInt(typeId) == 1003 then
            local vo = CardConfMgr:GetMonsterTypeVoById(checkInt(conditionPara))
            value = vo.name
        end
    end
    return value
end

function BattlingCombatLevelMgr:SetConditionDesc(desc, conditionPara, targetNum, typeId)
    desc = string.gsub(desc, "_target_num_", checkString(targetNum))
    desc = string.gsub(desc, "_diff_", checkString(self:FieldDiffTranslator(conditionPara, typeId)))
    return desc
end

function BattlingCombatLevelMgr:GetWaveEndConditionData(conditionId)
