end

function BattlingCombatLevelMgr:GetWaveEndConditionTypeData(conditionTypeId)
    local setting = SettingMgr:GetSetting(AutoIds.IdSetting756, "WaveEndConditionTypeVo")
    local data = setting:Get(conditionTypeId)
    return data
end

